/* ---------------- ScaleCamera (src/pilot/ScaleCamera.c) ---------------- */
/* ScaleCamera */
static inline void inv(MATRIX *a, MATRIX *b)
{
    b->m[0][0] = a->m[0][0];
    b->m[0][1] = a->m[1][0];
    b->m[0][2] = a->m[2][0];
    b->m[1][0] = a->m[0][1];
    b->m[1][1] = a->m[1][1];
    b->m[1][2] = a->m[2][1];
    b->m[2][0] = a->m[0][2];
    b->m[2][1] = a->m[1][2];
    b->m[2][2] = a->m[2][2];
}
void ScaleCamera(void)
{
    MATRIX temp;
    MATRIX temp2;
    MATRIX scale;
    MATRIX scaledcammat;
    VECTOR pos;
    SVECTOR tempang;

    tempang.vx = 0;
    tempang.vz = 0;
    pos.vz = 0;
    pos.vy = 0;
    pos.vx = 0;
    tempang.vy = *(unsigned short *)&D_00096C4A;
    RotMatrixYXZ(&tempang, &temp);

    inv(&temp, &temp2);

    scale.m[0][0] = 0x1000;
    scale.m[0][1] = 0;
    scale.m[0][2] = 0;
    scale.m[1][0] = 0;
    scale.m[1][1] = 0x1000;
    scale.m[1][2] = 0;
    scale.m[2][0] = 0;
    scale.m[2][1] = 0;
    scale.m[2][2] = 0x1000;

    MulMatrix0(&scale, &inv_camera_matrix, &scaledcammat);
    TransMatrix(&scaledcammat, &pos);
    SetRotMatrix(&scaledcammat);
    SetTransMatrix(&scaledcammat);
}

